export class ModelAuditOrchestrator {
  private catalog: RelationshipCatalog;
  private graph: RelationshipGraph;
  private initialized = false;

  constructor() {
    this.catalog = new RelationshipCatalog();
    this.graph = new RelationshipGraph();
  }

  async initialize(): Promise<void> {
    if (!this.initialized) {
      await this.catalog.load();
      this.initialized = true;
    }
  }

  /**
   * Get predicates applicable to a specific layer (same API as AuditOrchestrator)
   */
  getPredicatesForLayer(layer: string): string[] {
    return this.catalog.getTypesForLayer(layer).map((t) => t.predicate);
  }

  /**
   * Run complete audit against the project model
   */
  async runAudit(options: ModelAuditOptions = {}): Promise<AuditReport> {
    await this.initialize();

    const projectRoot = options.projectRoot ?? process.cwd();

    // Load model (layers + relationships)
    let model: Model;
    try {
      model = await Model.load(projectRoot);
    } catch (err) {
      throw new Error(
        `Failed to load project model from ${projectRoot}: ${err instanceof Error ? err.message : String(err)}`
      );
```","questions":{"layer":{"type":"choice","instructions":"Which Documentation Robotics architecture layer would this code symbol be recorded in if it were modelled as an element? Choose 'none' if it is not an architecturally meaningful element on its own.","criteria":{"motivation":"Motivation Layer (ArchiMate 3.2): Captures why the system exists: stakeholders and their drivers, assessments, goals and outcomes, principles, requirements and constraints, and the meaning and value attached to them (ArchiMate 3.2 motivation elements). Motivation elements are expressed in documents, decision records and requirement text rather than in executable code; every lower layer should be traceable back to an element here. Modelling rules: realization runs through motivation, as in ArchiMate: requirements realize the outcomes, goals and principles they make concrete, and outcomes realize goals. Decomposition is same-type only: an element aggregates the narrower elements of its own type that make it up, and specializes a more general one. Influence is one motivation element shaping another: drivers, assessments, stakeholders, goals, principles and constraints influence goals, outcomes, principles, requirements and constraints, and a constraint constrains the requirements it limits. Association is kept for concerns and interpretation: a stakeholder is associated with the drivers, goals, requirements, principles, outcomes and constraints it cares about, an assessment with the drivers it evaluates, and meaning and value are associated with any concept and are always the source of that association. Other layers trace to motivation with one predicate per meaning: they satisfy requirements, constraints and principles; an element realizes a goal or outcome it exists to achieve and supports one it contributes to alongside others; services and features deliver value, and user workflows deliver the outcomes they produce. A stakeholder is not served: business actors and roles, like personas, reference the stakeholder whose concerns they stand for. Example element types: Assessment, Constraint, Driver, Goal, Meaning, Outcome, Principle, Requirement.","business":"Business Layer (ArchiMate 3.2): Describes what the organization does independently of the software that supports it: business actors and roles, collaborations and interfaces, processes, functions, interactions and events, business services and business objects, and the business capabilities the organization has (ArchiMate 3.2 business layer, with the strategy layer's Capability). Elements here are realized by application services and consume no implementation detail. Modelling rules: actors fill roles, and roles and collaborations are assigned to the processes, functions and interactions they perform (assigned-to); behaviour is never assigned to an actor directly. Internal behaviour realizes business services, which interfaces offer (assigned-to) and which serve actors, roles and processes. Only behaviour accesses business objects and contracts; actors, roles and interfaces reach information through the behaviour assigned to them. Events trigger processes and interactions, and behaviour raises events (triggers); a hand-off between behaviours is flows-to, and a function, having no start, is reached by flows rather than triggered. A business capability is an ability the organization has: business functions and processes realize it, capabilities aggregate narrower capabilities, and software capabilities (product layer) contribute by realizing the business functions behind it. Business services and business capabilities carry the main link to motivation: services realize goals and outcomes, satisfy requirements and deliver value; capabilities support goals and realize outcomes; processes may also realize outcomes and satisfy requirements. Example element types: BusinessActor, BusinessCapability, BusinessCollaboration, BusinessEvent, BusinessFunction, BusinessInteraction, BusinessInterface, BusinessObject.","product":"Product Layer (ArchiMate 3.2 Strategy Extension + Product Management Practice): Frames the system from a product-management point of view: the personas it serves, the software capabilities it must possess, the features that deliver them, the user workflows that exercise them and the milestones that schedule delivery. It adapts the ArchiMate 3.2 strategy vocabulary rather than adopting it: a software capability is an ability of the software platform, not ArchiMate's Capability, which is the organization's ability and is modelled as business.businesscapability. Product elements describe what the software offers and to whom, never how it is built. Modelling rules: realization runs upward through product. Application and technology services realize software capabilities and features, views realize features, and navigation flows and flow steps realize user workflows and their steps; product elements in turn realize business behaviour, a software capability realizing the business function it carries out and a user workflow the business process the user performs. A feature realizes the software capabilities it exercises; software capabilities aggregate narrower capabilities, and capabilities and features may depend on their own kind. Features and user workflows serve the personas they are designed for; a persona describes a kind of person, so it references the stakeholder and business role it stands for rather than realizing or serving them. A user workflow composes its steps, steps flow to steps, and each step uses the features it exercises; a workflow reaches features and software capabilities only through its steps. Software capabilities support goals; software capabilities and features satisfy requirements; features deliver value and workflows deliver outcomes. Software capabilities and features are scheduled for milestones, and milestones precede milestones. Example element types: Feature, Milestone, Persona, SoftwareCapability, UserWorkflow, WorkflowStep.","security":"Security Layer (NIST SP 800-53): Defines how the system identifies, authorizes and protects: authentication configuration, roles, permissions, secure resources and their operations, access conditions and field-level controls, declarative policies and rules, data classification and rate limits, together with goal-oriented security concepts such as actors, objectives, delegations, threats, countermeasures and accountability (NIST SP 800-53 controls with STS-ml and XACML-style policy modelling). Code that checks identity or enforces permissions is evidence for elements here. Modelling rules: the security model composes its authentication configuration, constraints container and policies, and aggregates the shared elements (actors, roles, permissions, secure resources, information entities, delegations, threats, classifications and accountability requirements); a policy composes its rules, and a secure resource composes its operations and field access controls. Actors are assigned to roles, roles aggregate permissions and specialize a parent role, and permissions authorize resource operations; access follows that chain. An authentication configuration authenticates actors, uses its password policy and protects resources. A policy rule uses the conditions it evaluates, protects its target, authorizes permissions, triggers its policy actions and generates evidence; conditions and actions do not constrain or trigger on their own. Policies (security, password, retention and data classification) mandate the countermeasures they call for, and only countermeasures mitigate threats. A threat targets resources, information entities and business processes and services, influences classifications and policies, and references the motivation driver it gives rise to. Audit configurations, policy rules and delegations generate evidence; an audit configuration monitors resources and satisfies accountability requirements, and a retention policy governs the audit trails, evidence and information it keeps. A data classification governs the information entities, secure resources and retention policies it labels; field access controls are constrained by it, and data elements in other layers reference it. Separation of duty, binding of duty and need to know constrain roles, permissions and operations; the constraints container only groups them, and other layers link to the individual rule they follow. Validation rules constrain field values; they do not decide access. Example element types: AccessCondition, AccountabilityRequirement, Actor, AuditConfig, AuthenticationConfig, BindingOfDuty, Condition, Countermeasure.","application":"Application Layer (ArchiMate 3.2): Models the application architecture: application components (deployable modules, classes and services), the application functions and processes that describe their internal behaviour, the application services and interfaces through which that behaviour is exposed, application events and interactions, collaborations between components, and the data objects they process (ArchiMate 3.2 application layer). This is the default home for ordinary application code structure; more specific layers apply only when a symbol is itself an API contract, a data schema, a persistence object, a UI element, telemetry, security logic or a test asset. Modelling rules: components and collaborations are assigned to the functions, processes and interactions they perform (assigned-to), and a collaboration aggregates its components and nested collaborations. A component provides the interfaces its own code declares and is assigned to an interface it only handles; an interface is assigned to the services it offers. Functions, processes and interactions realize application services; a component may realize one directly, as a shortcut through the behaviour assigned to it. Services serve the components, functions, processes and interactions that use them. Functions, processes, interactions, events and services access data objects, and so do components, unlike in the business layer, because a component is code that holds and passes data; interfaces and collaborations do not. Functions, components and events also access the data-model object schemas and schema definitions they read and write, such as entity classes, directly rather than through a data object. Components, functions and services likewise access the data-store collections and views they read and write. Events trigger processes, interactions and functions (unlike a business function, an application function can be an event handler), and behaviour raises events. A hand-off between behaviours is flows-to; depends-on means one element needs another to work, and is never used where assigned-to, accesses, serves or triggers says it. Across layers, application processes and functions realize the business processes and functions they automate, and application services realize business services and product features and capabilities and, with the behaviour that realizes them, carry the link to motivation (realize goals, satisfy requirements and constraints, deliver value). Example element types: ApplicationCollaboration, ApplicationComponent, ApplicationEvent, ApplicationFunction, ApplicationInteraction, ApplicationInterface, ApplicationProcess, ApplicationService.","technology":"Technology Layer (ArchiMate 3.2): Models the infrastructure and platform the application runs on: nodes and devices, system software and runtimes, frameworks, communication networks and paths, technology services, interfaces, functions and processes, and the artifacts that are deployed to them (ArchiMate 3.2 technology layer). Package manifests, container images, deployment descriptors and infrastructure-as-code are the usual evidence. Modelling rules: nodes compose their devices, system software, interfaces and the artifacts deployed to them; nodes and system software are assigned to the functions and processes they perform, and a collaboration aggregates the nodes, system software and nested collaborations that cooperate in it and is assigned to its interactions. System software provides the interfaces it declares; an interface is assigned to the technology services it offers and serves the behaviour that uses it. Functions, processes and interactions realize technology services, and a node, system software, collaboration, path or network may realize one directly; a hand-off between behaviours is flows-to; events trigger behaviour, behaviour and services raise events, and structure does not trigger. Artifacts are passive: behaviour and system software access them, and they realize the system software they install and the application components they package, such as a container image. A communication network realizes the paths over it, and networks and paths connect the nodes and devices on them; other elements reach a network through the node they run on. Technology services serve nodes, other services and the application (components, services and functions); a node, device or system software may serve an application component directly as a shortcut for hosting it. Technology reaches the business layer through the application layer. Services carry the link to motivation: they realize goals and software capabilities and satisfy requirements; structure satisfies requirements, constraints and principles. Other layers reach technology in two ways: platform services serve the API, UX, APM, navigation and data-store elements that use them, and an element built on or run by a software product depends on that system software (a data-store database also depends on its node). Example element types: Artifact, CommunicationNetwork, Device, Node, Path, SystemSoftware, TechnologyCollaboration, TechnologyEvent.","api":"API Layer (OpenAPI 3.0): Describes the HTTP API surface the application exposes or consumes: the API document and its servers, paths and operations, parameters, request bodies and responses, media types, headers, links and callbacks, reusable components and schemas, security schemes and webhooks (OpenAPI 3.0). Route handlers, controllers and generated API clients are evidence for elements here; the application behaviour behind an operation belongs to the application layer. Modelling rules: each API object links only to what its OpenAPI 3.0 fields hold, and every nesting in the document tree is composes: the document composes its info, paths, components, servers and tags; paths compose path items, and a path item composes its operations, parameters and servers; an operation composes its parameters, request body, responses map, callbacks and servers; the responses map composes its responses, and a response composes its headers, media types and links; a media type composes its schema, examples and encodings; a server composes its variables, a security scheme its OAuth flows, and components their reusable entries. Reuse through $ref is references, and allOf inheritance is specializes. A rate limit, which OpenAPI does not define, governs the operations, path items and servers it caps, triggers its 429 response, references the headers and security scheme it counts by, and realizes its countermeasure. An operation realizes the application function it exposes and references its application service, and a document realizes its application service; the API reaches the business layer through the application layer. A security scheme realizes the security policy it applies, requires permissions and references the secure resource it protects. API schemas reach data stores and business objects through the data-model schemas that map to them. An operation satisfies requirements and constraints, supports the goals and outcomes it contributes to, and realizes the countermeasures it implements. Example element types: Callback, Components, Contact, Encoding, Example, ExternalDocumentation, Header, Info.","data-model":"Data Model Layer (JSON Schema Draft 7): Defines the logical data model: object schemas and their properties, enumerations, validation rules and the relationships between entities, independent of any particular storage technology (JSON Schema Draft 7). Entity classes, ORM models, DTO and record types, and type definitions that describe domain data are evidence for elements here; how that data is persisted belongs to the data-store layer. Modelling rules: data-model elements are passive structure; they are realized, accessed, referenced and mapped, and never serve, trigger or perform behaviour. A subschema written in place is part of what declares it (composes): a schema document composes its root schema and the definitions declared in it, an object schema composes its properties, an array schema its inline item schema, a composition its inline branches, and a property the value constraints it carries. A type declared elsewhere and reached by $ref or by name is referenced (references): a property references the object schema or definition its value takes, an array or composition references a named definition, and a Reference references the definition, object schema or document it points at. Subtyping is specializes. An entity class, an ORM model whatever the framework, or a type whose shape is published as a schema is an object schema; an in-code structure that only carries data between parts of the program is an application data object, which an object schema may realize. Object schemas and definitions realize the application data objects and business objects they give form to (a direct link to the business object is a shortcut through the data object), and map to their counterparts in other layers (maps-to): API schemas, request bodies, responses and parameters, and data-store collections. Behaviour reaches data by accessing it: application functions, components and events access object schemas and definitions, and business behaviour accesses the business objects they realize; a schema does not reference the behaviour that uses it. Schemas satisfy the requirements and constraints that govern the data but do not realize goals. The model is independent of technology: it does not depend on system software or use technology services, and the file that holds a schema document maps to a technology artifact. Example element types: ArraySchema, JSONSchema, NumericSchema, ObjectSchema, Reference, SchemaComposition, SchemaDefinition, SchemaProperty.","data-store":"Data Store Layer (ISO/IEC 9075 (SQL) + Paradigm Extensions): Describes physical persistence: databases and schemas, tables and collections, columns and fields, indexes, constraints, views, migrations, access patterns and the queries that read and write them (ISO/IEC 9075 SQL with extensions for document, key-value and graph paradigms). Migration scripts, table definitions and repository or DAO code that talks to storage are evidence for elements here. Modelling rules: containment is one level at a time: a database composes namespaces, or collections and views directly when the engine has none; a namespace composes collections, views, stored logic and nested namespaces; a collection composes its fields, indexes, validation rules and event handlers, and may compose partitions. Stored data is passive: collections, views, fields and databases are accessed, referenced and mapped, and never serve or trigger; application components, functions and services access the collections and views they read and write. Behaviour inside the store is stored logic, event handlers and access patterns: event handlers are attached to a collection, reference the fields they watch and trigger stored logic; stored logic accesses collections, triggers other stored logic and refreshes views; access patterns access a collection, use indexes and reference the fields in their key and filter conditions, and serve the application functions that issue them. Validation rules reference the fields they constrain, and a foreign key cascades to the collection it references. Views derive from collections and views; retention policies govern collections and namespaces, archive to collections and trigger the stored logic that purges them. Across layers, the store reaches the business through the application layer and the data model: stored logic realizes application functions, event handlers trigger application events, object schemas map to collections, and a collection may realize a business object as a shortcut; a view maps to the API response it backs. Example element types: AccessPattern, Collection, Database, EventHandler, Field, Index, Namespace, RetentionPolicy.","ux":"UX Layer (HTML 5.3): Models the user interface: views and screens, library components and their application-specific instances, forms, action and state patterns, component properties and the visual hierarchy they compose (HTML 5.3 vocabulary with component-library conventions). Rendered components, templates and view classes are evidence for elements here; the logic they call belongs to the application layer and the paths that reach them to the navigation layer. Modelling rules: placement is composition. A view composes its sub-views, component instances and action components; a sub-view or library sub-view composes its instances; an instance composes its nested instances, action components, slot references, chart series and table columns, and a menu composes its entries. A UX library aggregates its library components and sub-views, and a library component composes the components and slot references it is built from; an instance or placed sub-view realizes the library definition it places, and a slot reference references the component that fills it. Elements apply their layout configuration; state transitions, state patterns and action patterns use transition templates, which describe motion only. A state pattern aggregates its states; a state composes its outgoing transitions, a transition flows to its destination state, states and transitions trigger state actions, and a state action realizes its template. An action pattern governs the action components it is applied to. A view, sub-view, component instance or action component binds to its data configuration, which maps to the API or data-model data it reads; chart series and table columns bind through their component. Elements use their error configuration. A view realizes the application interface it presents and the product feature it delivers; an action component triggers the API operation or application behaviour it starts. UX does not access stores, operations or services directly, and reaches the business layer through the application interfaces and features it realizes: a view serves the business role it is for and references the business object it shows. A view supports the goals and outcomes it contributes to, and UX elements satisfy requirements and principles. Example element types: ActionComponent, ActionPattern, ChartSeries, ComponentInstance, ComponentReference, DataConfig, ErrorConfig, ExperienceState.","navigation":"Navigation Layer (SPA Navigation Patterns): Describes how a user moves through the application: routes and route parameters, navigation flows and their steps, guards and redirects, menus, deep links and the transitions between views (single-page-application navigation patterns). Router configuration and route tables are the usual evidence; the views reached belong to the UX layer and server-side HTTP endpoints to the API layer. Modelling rules: a navigation graph composes its routes and transitions and aggregates its flows, guards and breadcrumb configurations; a route composes its route meta and may contain child routes; a flow composes its steps and aggregates the context variables it carries. A transition leaves its source route (the route flows to it) and navigates to its destination route; a flow step navigates to its route, and a guard action redirects by navigating to a route. A guard evaluates its condition, triggers its action on denial and protects what it guards (routes, transitions, flows and flow steps); the condition and the action do not link to each other. Context variables are passive state: the steps, guards, conditions, actions and transitions that read or write them access them, and their value types map to data-model schema properties or reference data objects and schema documents. A breadcrumb configuration references the route meta it reads labels from, its home route and the flows it shows progress for. Across layers, a route maps to the UX view it renders and may lazy-load or depend on application components; routes, steps and guards use application services, access the data-model schemas they load or check, and are served by the API operations they call; they never reach the data store directly. Navigation reaches the business and motivation layers through the product user workflows and workflow steps that flows and steps realize, and satisfies requirements, constraints and principles. Example element types: BreadcrumbConfig, ContextVariable, FlowStep, GuardAction, GuardCondition, NavigationFlow, NavigationGraph, NavigationGuard.","apm":"APM Observability Layer (OpenTelemetry): Defines how the system is observed in operation: instrumentation and telemetry configuration, metrics, spans and traces, logs, alerts, dashboards and service-level objectives, with the resources and attributes that describe them (OpenTelemetry 1.0). Logging, metrics and tracing code, exporters and alerting rules are evidence for elements here. Modelling rules: a resource identifies the producing entity: it aggregates the instrumentation scopes running in it, maps to the application component it describes and references its node and system software. A scope aggregates the spans, metric instruments and log records emitted under it, which inherit the resource through it; a span composes its events and aggregates its links. Trace, metric and log configurations (providers) depend on the resource they are built with and aggregate their processors and exporters; they configure telemetry and do not emit, serve or monitor it. An instrumentation configuration monitors the library or code it instruments and references the scope it emits under. Each signal flows through its own processors to exporters, and an exporter accesses the storage it writes to and is served by the technology service it sends to; signals of different kinds are correlated by references (a log record to its span, a metric's exemplars to spans, a span link to its span), not by flow. Only signals and instrumentation configurations monitor elements in other layers; alerts and dashboards monitor signals, and a dashboard references the alerts it shows. Telemetry reaches the business layer only through business KPIs, metric instruments that monitor business processes and services; a metric that tracks an outcome measures it, and telemetry satisfies requirements and constraints. Example element types: Alert, Dashboard, ExporterConfig, InstrumentationConfig, InstrumentationScope, LogConfiguration, LogProcessor, LogRecord.","testing":"Testing Layer (IEEE 829-2008): Describes how the system is verified: test strategies and plans, suites and cases, fixtures and test data, mocks and stubs, coverage targets and summaries, and the environments tests run in (IEEE 829-2008 test documentation). Test files, fixtures and test configuration are evidence for elements here; the production code under test belongs to the layer it implements. Modelling rules: each testing type has one composing parent. A test coverage model composes its coverage targets, input space partitions, context variations, environment factors, exclusions and coverage summary; a coverage target composes its target input fields, outcome categories, coverage requirements and test case sketches; a coverage requirement composes its input partition selections; a partition composes its values; a test case sketch composes its input selections. A test case sketch validates the one coverage requirement it exercises and references the context variation and outcome category it combines; each input selection references the partition value it picks. A coverage requirement references the context variations and outcome categories it needs, and reaches partition values only through its selections. A target input field references its partition and the field under test (an API parameter, schema property or UX component), so partitions stay reusable across fields; a selection references the values it picks, and a partition dependency references its trigger value and the partition it affects. Summaries report and never validate: a coverage summary aggregates the per-target summaries, a target coverage summary references its target, and both reference the gaps and exclusions they count. Gaps and exclusions reference the requirement or target they concern, and an exclusion references the gap it waives. Context variations reference the environment factors they fix, and environment factors reference only technology nodes and system software. A coverage target covers the production artifact it names; a test case sketch tests what it exercises, requires the software it runs on and accesses the stores holding its fixture data; the model covers only the application component, UX application or API document it is for. Requirements and summaries reach no other layer. The model carries the plan-level motivation links (it supports goals, satisfies principles, constraints and requirements, and measures outcomes), and test case sketches satisfy the requirements they verify. Example element types: ContextVariation, CoverageExclusion, CoverageGap, CoverageRequirement, CoverageSummary, EnvironmentFactor, InputPartitionSelection, InputSelection.","none":"Not an architecturally meaningful element on its own: a trivial helper, formatting utility, boilerplate, generated code, test scaffolding, or an implementation detail below the level a 13-layer architecture model would record."}},"significance":{"type":"score","instructions":"How architecturally significant is this symbol within its codebase?","criteria":["0: implementation detail (private helper, formatter, trivial wrapper, constant)","1: minor internal unit that only its file cares about","2: notable internal unit a maintainer would name when explaining the module","3: architecturally significant (a service, component, contract, store, policy or integration point)","4: core architectural element: an entry point, system boundary, or central abstraction"]},"concern_authentication":{"type":"noul","instructions":"This symbol itself implements the authentication concern (verifies identity: login, tokens, API keys, sessions, credentials), not merely calling something that does."},"concern_authorization":{"type":"noul","instructions":"This symbol itself implements the authorization concern (decides what an identity may do: roles, permissions, policies, access checks), not merely calling something that does."},"concern_data_persistence":{"type":"noul","instructions":"This symbol itself implements the data persistence concern (reads or writes durable storage: files, databases, caches, manifests on disk), not merely calling something that does."},"concern_external_integration":{"type":"noul","instructions":"This symbol itself implements the external integration concern (calls or serves an external system or process: HTTP clients, MCP servers, subprocesses, third-party APIs), not merely calling something that does."},"concern_observability":{"type":"noul","instructions":"This symbol itself implements the observability concern (telemetry, logging, metrics, tracing, spans), not merely calling something that does."},"concern_user_interface":{"type":"noul","instructions":"This symbol itself implements the user interface concern (renders or drives a user-facing interface: CLI output, web UI, TUI, prompts), not merely calling something that does."}}}

